353	<body>
354	  <main>
355	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - press Space to toggle, double-click to change color" aria-pressed="false" aria-describedby="hint-text">
356	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
357	        <circle cx="200" cy="200" r="200"/>
358	      </svg>
359	    </button>
360	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
361	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click to activate • Double-click to change color</div>
362	    <div class="controls" role="group" aria-label="Circle controls">
363	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
364	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
365	    </div>
366	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
367	  </main>
368	
369	  <script defer>
370	    const CONFIG = {
371	      storageKey: 'circle-state',
372	      tapDelay: 300,
373	      colorShiftDuration: 500,
374	      colorModes: [
375	        { class: 'default', name: 'Default White' },
376	        { class: 'color-mode-1', name: 'Pink' },
377	        { class: 'color-mode-2', name: 'Teal' },
378	        { class: 'color-mode-3', name: 'Mint' }
379	      ],
380	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0,
381	      pulseInterval: 2500
382	    };
383	
384	    const el = {
385	      circle: document.getElementById('decorative-circle'),
386	      hint: document.getElementById('hint-text'),
387	      modeIndicator: document.getElementById('mode-indicator'),
388	      cycleBtn: document.getElementById('cycle-btn'),
389	      resetBtn: document.getElementById('reset-btn')
390	    };
391	
392	    let state = { active: false, colorMode: 0 };
393	    let tapCount = 0;
394	    let tapTimeout = null;
395	    let animatingColorShift = false;
396	
397	    const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
398	    const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
399	
400	    const storage = {
401	      save() {
402	        try {
403	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
404	        } catch {
405	          // Silently fail if localStorage is unavailable or quota exceeded
406	        }
407	      },
408	      load() {
409	        try {
410	          const saved = localStorage.getItem(CONFIG.storageKey);
411	          if (saved) {
412	            const parsed = JSON.parse(saved);
413	            if (parsed && typeof parsed === 'object') {
414	              state = { ...state, ...parsed };
415	            }
416	          }
417	        } catch {
418	          // Silently fail if parsing fails
419	        }
420	      }
421	    };
422	
423	    const updateClasses = () => {
424	      const colorClasses = CONFIG.colorModes.map(m => m.class);
425	      el.circle.classList.remove('active', ...colorClasses);
426	      el.circle.setAttribute('aria-pressed', state.active);
427	      if (state.active) el.circle.classList.add('active');
428	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
429	    };
430	
431	    const updateUI = () => {
432	      const mainText = state.active ? 'Active!' : 'Click to activate';
433	      let hintParts = [mainText];
434	
435	      if (CONFIG.isTouch) {
436	        hintParts.push(state.active ? 'Tap to change color' : 'Tap twice to change color');
437	      } else {
438	        hintParts.push(state.active ? 'Double-click to cycle colors' : 'Double-click to change color');
439	      }
440	
441	      el.hint.textContent = hintParts.join(' • ');
442	
443	      const showMode = state.active && state.colorMode > 0;
444	      el.modeIndicator.classList.toggle('visible', showMode);
445	      if (showMode) {
446	        const modeName = getColorModeName(state.colorMode);
447	        el.modeIndicator.textContent = `${modeName.toUpperCase()} MODE`;
448	      }
449	    };
450	
451	    const applyState = () => {
452	      updateClasses();
453	      updateUI();
454	    };
455	
456	    const toggleActive = () => {
457	      state.active = !state.active;
458	      applyState();
459	      storage.save();
460	    };
461	
462	    const cycleColor = () => {
463	      if (animatingColorShift) return;
464	      animatingColorShift = true;
465	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
466	      state.active = true;
467	      el.circle.classList.add('color-shifting');
468	      setTimeout(() => {
469	        el.circle.classList.remove('color-shifting');
470	        animatingColorShift = false;
471	      }, CONFIG.colorShiftDuration);
472	      applyState();
473	      storage.save();
474	    };
475	
476	    const resetState = () => {
477	      state = { active: false, colorMode: 0 };
478	      applyState();
479	      storage.save();
480	    };
481	
482	    const handleDblClick = (e) => {
483	      e.preventDefault();
484	      if (!state.active) {
485	        state.active = true;
486	        applyState();
487	      }
488	      cycleColor();
489	    };
490	
491	    const handleTouchEnd = () => {
492	      tapCount++;
493	      clearTimeout(tapTimeout);
494	      if (tapCount === 1) {
495	        tapTimeout = setTimeout(() => {
496	          if (tapCount === 1) toggleActive();
497	          tapCount = 0;
498	        }, CONFIG.tapDelay);
499	      } else if (tapCount === 2) {
500	        cycleColor();
501	        tapCount = 0;
502	      }
503	    };
504	
505	    const keyHandlers = {
506	      ' ': toggleActive,
507	      'enter': toggleActive,
508	      'c': cycleColor,
509	      'r': resetState
510	    };
511	
512	    const handleKeyDown = (e) => {
513	      const handler = keyHandlers[e.key.toLowerCase()];
514	      if (handler) {
515	        e.preventDefault();
516	        handler();
517	      }
518	    };
519	
520	    const initListeners = () => {
521	      el.circle.addEventListener('click', toggleActive);
522	      el.circle.addEventListener('dblclick', handleDblClick);
523	      el.circle.addEventListener('touchend', handleTouchEnd);
524	      el.circle.addEventListener('blur', () => {
525	        tapCount = 0;
526	        clearTimeout(tapTimeout);
527	      });
528	      document.addEventListener('keydown', handleKeyDown);
529	      el.cycleBtn.addEventListener('click', cycleColor);
530	      el.resetBtn.addEventListener('click', resetState);
531	    };
532	
533	    const initApp = () => {
534	      storage.load();
535	      applyState();
536	      initListeners();
537	      requestAnimationFrame(() => el.circle.focus());
538	    };
539	
540	    if (document.readyState === 'loading') {
541	      document.addEventListener('DOMContentLoaded', initApp);
542	    } else {
543	      initApp();
544	    }
545	  </script>
546	</body>
547	</html>
